-- Catálogo inicial obtenido del listado público de cursos de DevTalles.
-- Verificado: 2026-09-14. Las categorías son una clasificación interna del proyecto.
-- Este script está pensado para PostgreSQL y se puede ejecutar más de una vez.

CREATE TABLE IF NOT EXISTS courses (
    course_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    slug VARCHAR(160) NOT NULL UNIQUE,
    title VARCHAR(255) NOT NULL,
    course_url TEXT NOT NULL,
    image_url TEXT NOT NULL,
    image_alt VARCHAR(255) NOT NULL,
    track VARCHAR(40) NOT NULL,
    level VARCHAR(20),
    topics JSONB NOT NULL DEFAULT '[]'::jsonb,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    source_verified_at DATE NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT ck_courses_track CHECK (track IN (
        'Fundamentos', 'Frontend', 'Backend', 'CSharp', 'Datos',
        'IA', 'Movil', 'Herramientas', 'Automatizacion'
    )),
    CONSTRAINT ck_courses_level CHECK (level IS NULL OR level IN (
        'Principiante', 'Intermedio', 'Avanzado'
    )),
    CONSTRAINT ck_courses_url CHECK (course_url LIKE 'https://cursos.devtalles.com/courses/%'),
    CONSTRAINT ck_courses_image_url CHECK (image_url LIKE 'https://import.cdn.thinkific.com/%')
);


-- Compatibilidad por si la tabla ya existía antes de agregar portadas.
ALTER TABLE courses ADD COLUMN IF NOT EXISTS image_url TEXT;
ALTER TABLE courses ADD COLUMN IF NOT EXISTS image_alt VARCHAR(255);

CREATE INDEX IF NOT EXISTS ix_courses_track_active ON courses (track, is_active);

ON CONFLICT (slug) DO UPDATE SET
    title = EXCLUDED.title,
    course_url = EXCLUDED.course_url,
    image_url = EXCLUDED.image_url,
    image_alt = EXCLUDED.image_alt,
    track = EXCLUDED.track,
    is_active = TRUE,
    source_verified_at = EXCLUDED.source_verified_at,
    updated_at = NOW();

-- Comprobación esperada: 72 filas.
SELECT COUNT(*) AS seeded_courses FROM courses;
